//! The line icons the directory index draws, on the same 24-unit grid and 1.5
//! stroke as everything else serv renders.

/// What an entry looks like at a glance.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
  Folder,
  Html,
  Css,
  Js,
  File,
}

impl Kind {
  /// Pick an icon from the file name. Directories are decided by the caller.
  pub fn of(name: &str) -> Self {
    match extension(name).as_deref() {
      Some("html" | "htm") => Kind::Html,
      Some("css") => Kind::Css,
      Some("js" | "mjs" | "cjs") => Kind::Js,
      _ => Kind::File,
    }
  }

  /// The icon's paths, spliced into a `<svg>` the template already opened.
  pub fn icon(self) -> &'static str {
    match self {
      Kind::Folder => FOLDER,
      Kind::Html => HTML,
      Kind::Css => CSS,
      Kind::Js => JS,
      Kind::File => FILE,
    }
  }
}

fn extension(name: &str) -> Option<String> {
  let (_, ext) = name.rsplit_once('.')?;
  (!ext.is_empty()).then(|| ext.to_ascii_lowercase())
}

